:root{color-scheme:light;--ink:#183b35;--muted:#536a62;--green:#1f604c;--line:#d4ded5;--paper:#fffef9;--wash:#eef3ec;--error:#a02b22;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--wash);color:var(--ink);line-height:1.55}header,main,footer{width:min(1040px,calc(100% - 40px));margin-inline:auto}.page-header{padding:35px 0 22px}.back-link{font-size:.9rem;color:var(--green)}.eyebrow{letter-spacing:.14em;font-size:.75rem;font-weight:750;margin:23px 0 6px;color:var(--green)}h1{font-family:Georgia,serif;font-size:clamp(2.35rem,5vw,3.6rem);font-weight:500;line-height:1.12;margin:0}h2{font-size:1.35rem;margin:0 0 .5rem}h3{font-size:1.15rem;margin:0}p{margin:.5rem 0 1rem}.intro{font-size:1.12rem;max-width:620px;margin-top:14px}.card,.visit-card{background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:25px;margin-bottom:20px;box-shadow:0 3px 10px #203b3010}.actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center}button{font:inherit;font-weight:650;background:var(--green);color:white;border:1px solid var(--green);border-radius:7px;padding:11px 17px;cursor:pointer;min-height:44px}button.secondary{background:transparent;color:var(--green)}button:disabled{opacity:.45;cursor:not-allowed}button:hover:not(:disabled){filter:brightness(.93)}:focus-visible{outline:3px solid #bc7400;outline-offset:3px}.muted,.field-help{color:var(--muted);font-size:.9rem}.muted{margin-top:16px}.error{color:var(--error);font-weight:650;white-space:pre-wrap}.error:empty,[role=status]:empty{display:none}.preview{border-left:4px solid #ad7922;background:#f6efdd;padding:20px;margin-top:18px}.preview h3{margin-bottom:10px}.source-card .eyebrow{margin-top:0}.source-name{font-weight:650;overflow-wrap:anywhere;white-space:pre-wrap}.notice{border-top:1px solid var(--line);padding-top:14px;font-size:.9rem;color:var(--muted);margin-bottom:0}details summary{cursor:pointer;font-weight:650}dl{margin:14px 0}dt{font-weight:650}dd{margin:0 0 8px;white-space:pre-wrap;overflow-wrap:anywhere}.record-toolbar{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:10px}.record-toolbar p{margin:4px 0}.record-toolbar>.field-help,.record-toolbar>.error,.record-toolbar>#saveStatus{flex-basis:100%}.visits{list-style:none;padding:0;margin:0;counter-reset:visit}.visit-card{counter-increment:visit}.visit-heading{display:flex;gap:12px;align-items:flex-start}.visit-heading::before{content:counter(visit);background:#e4eadc;border-radius:50%;font-size:.85rem;font-weight:750;width:30px;height:30px;flex:0 0 30px;text-align:center;line-height:30px}.visit-heading h3{overflow-wrap:anywhere}.planned{font-weight:600;color:var(--green);margin:12px 0 4px}.why{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted);font-size:.94rem}.visit-fields{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;border-top:1px solid var(--line);padding-top:16px;margin-top:16px}label{display:block;font-weight:650}input,select,textarea{display:block;width:100%;margin-top:6px;border:1px solid #8a9c92;border-radius:6px;background:white;color:var(--ink);font:inherit;padding:10px;min-height:45px}textarea{resize:vertical;min-height:95px}input[aria-invalid=true],textarea[aria-invalid=true]{border:2px solid var(--error)}.note-field{grid-column:1/-1}.field-error{display:block;color:var(--error);font-size:.88rem;white-space:pre-wrap}.field-error:empty{display:none}.note-help{display:block;font-size:.83rem;font-weight:400;color:var(--muted);margin-top:5px}.print-values{display:none}footer{padding:5px 0 35px;font-size:.85rem;color:var(--muted)}[hidden]{display:none!important}
@media(max-width:600px){header,main,footer{width:calc(100% - 24px)}.page-header{padding-top:22px}.card,.visit-card{padding:18px;border-radius:10px}.visit-fields{grid-template-columns:1fr;gap:13px}.record-toolbar>.actions{width:100%}.record-toolbar>.actions button{flex:1}.source-name{font-size:.92rem}.intro{font-size:1rem}.actions button{padding:10px 13px}}
@media print{body{background:white;color:#111;font-size:10pt}header,main,footer{width:100%}.page-header{padding:0 0 12px}.back-link,.no-print,.empty,details,.visit-fields{display:none!important}h1{font-size:25pt}.eyebrow{margin:7px 0}.card,.visit-card{box-shadow:none;border-color:#bbb;border-radius:0;padding:12px;break-inside:avoid;margin-bottom:12px}.print-values{display:block;white-space:pre-wrap;overflow-wrap:anywhere}.notice,.why,.muted{color:#333}.record-toolbar .field-help{display:none}body.invalid-draft #visits{display:none}footer{padding-bottom:0}}

import { createVisitRecord, updateVisitRecord, visitRecordRows, makeVisitRecordFile, readVisitRecord, VISIT_RECORD_LIMITS } from "./visit_record.mjs";
import { readWeekFile } from "./week_file.mjs";
import { renderVisitRecordCsv } from "./visit_record_csv.mjs";
import { createVisitEditHistory } from "./visit_edit_history.mjs";

const $ = selector => document.querySelector(selector);
const labels = {unrecorded: "Unrecorded", went: "Went", did_not_go: "Did not go"};
let current = null, pending = null, generation = 0, downloadUrl = null;
const invalid = new Map();
const editHistory = createVisitEditHistory();
function text(tag, value, className) {
  const node = document.createElement(tag); node.textContent = value;
  if (className) node.className = className;
  return node;
}
function retire(message = "") {
  generation++; pending = null;
  $("#preview").hidden = true; $("#cancelOpen").hidden = true;
  $("#fileStatus").textContent = message; $("#fileError").textContent = "";
}
function controls() {
  const blocked = !current || invalid.size > 0;
  $("#saveRecord").disabled = blocked; $("#printRecord").disabled = blocked;
  $("#downloadCsv").disabled = blocked;
  $("#undoChange").disabled = blocked || !editHistory.canUndo;
  $("#redoChange").disabled = blocked || !editHistory.canRedo;
  $("#historyHelp").textContent = invalid.size ? "Correct the marked fields before using Undo or Redo. Invalid text is not discarded." : "Undo or redo up to 20 visit edits in this tab. Using another file starts a new history.";
  document.body.classList.toggle("invalid-draft", invalid.size > 0);
  $("#draftError").textContent = invalid.size ? "Correct the marked fields before downloading or printing. Your earlier valid values remain in this tab." : "";
  if (current) {
    const counts = Object.fromEntries(Object.keys(labels).map(outcome => [outcome, current.visits.filter(v => v.outcome === outcome).length]));
    $("#recordSummary").textContent = `${counts.went} went · ${counts.did_not_go} did not go · ${counts.unrecorded} unrecorded`;
  }
}
function printText(row) {
  return `Outcome: ${labels[row.outcome]}\nVisit or decision date: ${row.date ?? "Not recorded"}\nNote: ${row.note || "No note"}`;
}
function render() {
  const saved = readWeekFile(current.source.weekText), rows = visitRecordRows(current);
  $("#emptyState").hidden = true; $("#record").hidden = false;
  $("#recordTitle").textContent = "Week of " + saved.state.weekStart;
  $("#sourceName").textContent = current.source.name;
  const mode = {mock:"Demo plan: fictional venues from a synthetic fixture.",live:"Original live plan.",unknown:"Original source mode was not recorded."}[saved.state.sourceMode];
  $("#sourceFacts").textContent = mode + " " + rows.length + " original picks.";
  $("#sourceProvenance").textContent = "Original response received " + saved.receivedAt + ". Week copy saved " + saved.savedAt + ". Planned dates and explanations below come from that copy.";
  $("#sourceInputs").replaceChildren();
  for (const key of ["city", "cuisines", "music", "films", "constraints"]) {
    const value = saved.inputs[key];
    $("#sourceInputs").append(text("dt", key[0].toUpperCase() + key.slice(1)), text("dd", Array.isArray(value) ? value.join(", ") || "None requested" : value));
  }
  $("#originalNotes").replaceChildren(...saved.response.plan.notes.map(value => text("li", value)));
  $("#visits").replaceChildren();
  for (const row of rows) {
    const card = text("li", "", "visit-card"); card.dataset.key = row.key;
    const heading = text("div", "", "visit-heading");
    heading.append(text("h3", row.pick.name)); card.append(heading);
    card.append(text("p", row.plannedDate ? "Planned: " + row.plannedDay + ", " + row.plannedDate : "Not scheduled in this saved week", "planned"));
    card.append(text("p", "Original suggestion: " + row.originalDay + " · " + row.pick.kind, "muted"));
    card.append(text("p", row.pick.why, "why"));
    const fields = text("div", "", "visit-fields");
    for (const field of ["outcome", "date", "note"]) {
      const label = text("label", {outcome:"Outcome",date:"Visit or decision date (optional)",note:"What would you like to remember?"}[field], field === "note" ? "note-field" : "");
      const input = document.createElement(field === "outcome" ? "select" : field === "note" ? "textarea" : "input");
      input.id = row.key + "-" + field; input.dataset.field = field; input.dataset.key = row.key;
      if (field === "outcome") for (const [value, title] of Object.entries(labels)) { const option = text("option", title); option.value = value; input.append(option); }
      if (field === "date") { input.type = "text"; input.inputMode = "numeric"; input.placeholder = "YYYY-MM-DD"; input.autocomplete = "off"; }
      if (field === "note") input.rows = 3;
      input.value = row[field] ?? "";
      const error = text("span", "", "field-error"); error.id = input.id + "-error";
      input.setAttribute("aria-describedby", error.id + (field === "note" ? " " + input.id + "-help" : ""));
      label.append(input, error);
      if (field === "note") { const help = text("span", "Optional · up to 4,000 characters. Keep private health details out.", "note-help"); help.id = input.id + "-help"; label.append(help); }
      input.addEventListener(field === "outcome" ? "change" : "input", () => edit(row.key, field, input, error, card));
      input.addEventListener("blur", () => { editHistory.close(); controls(); });
      fields.append(label);
    }
    card.append(fields, text("p", printText(row), "print-values")); $("#visits").append(card);
  }
  if (!rows.length) $("#visits").append(text("li", "This saved week has no original picks. Its source can still be saved with this record.", "card"));
  controls();
}
function edit(key, field, input, error, card) {
  retire("File preview cleared because you edited this record.");
  $("#saveStatus").textContent = "";
  const id = key + ":" + field;
  try {
    // Read only this edited field. In particular, unrelated edits never normalize
    // an imported literal CR/CRLF note through textarea.value.
    const value = field === "date" && input.value === "" ? null : input.value;
    const next = updateVisitRecord(current, key, { [field]: value });
    current = editHistory.record(next, input.id, field !== "outcome");
    invalid.delete(id); input.removeAttribute("aria-invalid"); error.textContent = "";
    card.querySelector(".print-values").textContent = printText(current.visits.find(v => v.key === key));
  } catch (e) { invalid.set(id, e.message); input.setAttribute("aria-invalid", "true"); error.textContent = e.message; }
  controls();
}
function recover(direction) {
  if (!current || invalid.size) return;
  const change = editHistory[direction]();
  if (!change) return;
  retire("File preview cleared because you recovered an edit.");
  const position = {x: window.scrollX, y: window.scrollY};
  current = change.record;
  render();
  document.getElementById(change.target)?.focus({preventScroll:true});
  window.scrollTo(position.x, position.y);
  $("#saveStatus").textContent = direction === "undo" ? "Undid the last visit edit." : "Redid the visit edit.";
}
async function open(file, kind) {
  editHistory.close(); controls();
  retire(file ? "Reading file… The displayed record stays in place." : "");
  if (!file) return;
  const version = generation;
  $("#cancelOpen").hidden = false;
  try {
    if (!Number.isSafeInteger(file.size) || file.size < 0 || file.size > VISIT_RECORD_LIMITS.fileBytes) throw new TypeError("Choose a JSON file no larger than 8 MiB.");
    const bytes = new Uint8Array(await file.arrayBuffer());
    if (bytes.byteLength > VISIT_RECORD_LIMITS.fileBytes) throw new TypeError("Choose a JSON file no larger than 8 MiB.");
    // ignoreBOM:true retains an initial BOM as part of the original source text.
    let content;
    try { content = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes); }
    catch { throw new TypeError("Choose a valid UTF-8 file."); }
    const candidate = kind === "week" ? {record:createVisitRecord(content, file.name), savedAt:null} : readVisitRecord(content);
    if (version !== generation) return;
    const saved = readWeekFile(candidate.record.source.weekText);
    pending = candidate;
    $("#previewSummary").textContent = candidate.record.source.name + " · week of " + saved.state.weekStart + " · " + candidate.record.visits.length + " original picks" + (candidate.savedAt ? " · visit record saved " + candidate.savedAt : " · all outcomes start unrecorded") + ".";
    $("#preview").hidden = false; $("#fileStatus").textContent = "File checked. Review it before using.";
    $("#previewTitle").focus({preventScroll:true});
  } catch (e) {
    if (version !== generation) return;
    pending = null; $("#preview").hidden = true; $("#cancelOpen").hidden = true;
    $("#fileStatus").textContent = ""; $("#fileError").textContent = "Could not open this file: " + e.message;
  }
}
for (const [kind, button, picker] of [["week","#openWeek","#weekFile"],["record","#openRecord","#recordFile"]]) {
  $(button).addEventListener("click", () => { retire(); $(picker).value = ""; $(picker).click(); });
  $(picker).addEventListener("change", () => { void open($(picker).files[0], kind); });
  $(picker).addEventListener("cancel", () => retire("Opening cancelled. Your current record is unchanged."));
}
$("#cancelOpen").addEventListener("click", () => retire("Opening cancelled. Your current record is unchanged."));
$("#useRecord").addEventListener("click", () => {
  if (!pending) return;
  const next = pending.record; retire(); current = next; editHistory.reset(current); invalid.clear();
  $("#saveStatus").textContent = ""; render(); $("#recordTitle").focus({preventScroll:true});
});
$("#saveRecord").addEventListener("click", () => {
  if (!current || invalid.size) return;
  retire();
  try {
    const file = makeVisitRecordFile(current);
    if (downloadUrl) URL.revokeObjectURL(downloadUrl);
    downloadUrl = URL.createObjectURL(new Blob([file.text], {type:"application/json;charset=utf-8"}));
    const link = document.createElement("a"); link.href = downloadUrl; link.download = file.filename;
    document.body.append(link); link.click(); link.remove();
    $("#saveStatus").textContent = "Download requested. Keep the JSON file to reopen this record.";
  } catch (e) { $("#saveStatus").textContent = "Could not save this record: " + e.message; }
});
$("#downloadCsv").addEventListener("click", () => {
  if (!current || invalid.size) return;
  retire();
  try {
    const report = renderVisitRecordCsv(makeVisitRecordFile(current).text);
    if (downloadUrl) URL.revokeObjectURL(downloadUrl);
    downloadUrl = URL.createObjectURL(new Blob([report.csv], {type:"text/csv;charset=utf-8"}));
    const link = document.createElement("a"); link.href = downloadUrl; link.download = `tastetable-visits-${report.weekStart}.csv`;
    document.body.append(link); link.click(); link.remove();
    $("#saveStatus").textContent = "CSV download requested. Keep the JSON file to reopen and edit this record.";
  } catch (e) { $("#saveStatus").textContent = "Could not download this CSV report: " + e.message; }
});
$("#printRecord").addEventListener("click", () => { if (current && !invalid.size) { retire(); window.print(); } });
window.addEventListener("pagehide", () => { if (downloadUrl) URL.revokeObjectURL(downloadUrl); });

$("#undoChange").addEventListener("click", () => recover("undo"));
$("#redoChange").addEventListener("click", () => recover("redo"));
// Close an edit even for an explicit button action that does not move focus.
// Keep the existing JSON, CSV and Print handlers unchanged.
document.addEventListener("click", event => {
  if (event.target instanceof Element && event.target.closest("button")) {
    editHistory.close(); controls();
  }
}, true);
window.addEventListener("pagehide", () => { editHistory.reset(current); controls(); });

/** Local, explicit visit outcomes bound to original saved-week occurrences. */
import { readWeekFile } from "./week_file.mjs";
import { calendarWeek } from "./week_plan.mjs";

export const VISIT_RECORD_FORMAT = "tastetable.visit-record.v1";
export const VISIT_RECORD_LIMITS = Object.freeze({
  sourceBytes: 2 * 1024 * 1024, fileBytes: 8 * 1024 * 1024,
  occurrences: 100, nameCodePoints: 512, noteCodePoints: 4000,
});
const outcomes = new Set(["unrecorded", "went", "did_not_go"]);
const utf8 = new TextEncoder();
const fail = (condition, message) => { if (!condition) throw new TypeError(message); };

function fields(value, expected, label) {
  fail(value !== null && typeof value === "object" && !Array.isArray(value)
    && [Object.prototype, null].includes(Object.getPrototypeOf(value)),
  label + " must be a plain record.");
  const keys = Reflect.ownKeys(value);
  fail(keys.length === expected.length && expected.every(key => keys.includes(key))
    && expected.every(key => Object.hasOwn(Object.getOwnPropertyDescriptor(value, key), "value")),
  label + " has missing or unsupported fields.");
}
function unicode(text, label) {
  fail(typeof text === "string" && text.isWellFormed(), label + " must contain valid Unicode text.");
}
function boundedText(text, maxBytes, label) {
  unicode(text, label);
  fail(utf8.encode(text).byteLength <= maxBytes, label + " is too large.");
}
function name(value) {
  unicode(value, "Source name");
  fail(value.trim().length > 0 && [...value].length <= VISIT_RECORD_LIMITS.nameCodePoints
    && !/[\u0000-\u001f\u007f]/u.test(value),
  "Use a nonblank source name of at most 512 characters, without control characters.");
  return value;
}
function note(value) {
  unicode(value, "Visit note");
  fail([...value].length <= VISIT_RECORD_LIMITS.noteCodePoints
    && !/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u.test(value),
  "Use at most 4,000 characters in a note; only tabs and line breaks are allowed as control characters.");
  return value;
}
function visitDate(value) {
  if (value === null) return null;
  fail(typeof value === "string" && /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)
    && value.slice(0, 4) !== "0000", "Use a real date in YYYY-MM-DD form, within years 0001–9999.");
  const parsed = new Date(value + "T12:00:00.000Z");
  fail(Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === value,
    "Use a real calendar date in YYYY-MM-DD form.");
  return value;
}
function timestamp(value) {
  fail(typeof value === "string", "The visit record needs a saved timestamp.");
  const date = new Date(value);
  fail(Number.isFinite(date.getTime()) && date.toISOString() === value,
    "The visit record needs a canonical saved timestamp.");
  return value;
}
function freeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.values(value).forEach(freeze);
    Object.freeze(value);
  }
  return value;
}
function source(value) {
  fields(value, ["name", "weekText"], "Source");
  name(value.name);
  boundedText(value.weekText, VISIT_RECORD_LIMITS.sourceBytes, "Original saved week");
  const saved = readWeekFile(value.weekText);
  fail(saved.state.picks.length <= VISIT_RECORD_LIMITS.occurrences,
    "Choose a saved week with at most 100 original picks.");
  return saved;
}
function entry(value) {
  fields(value, ["key", "outcome", "date", "note"], "Visit");
  fail(typeof value.key === "string" && outcomes.has(value.outcome), "The visit has an unsupported key or outcome.");
  return { key: value.key, outcome: value.outcome, date: visitDate(value.date), note: note(value.note) };
}
function normalize(record) {
  fields(record, ["source", "visits"], "Visit record");
  const saved = source(record.source), keys = saved.state.picks.map(pick => pick.key);
  fail(Array.isArray(record.visits) && record.visits.length === keys.length,
    "Include every original pick exactly once.");
  const entries = new Map();
  for (const raw of record.visits) {
    const value = entry(raw);
    fail(keys.includes(value.key) && !entries.has(value.key), "The visit record has an unknown or repeated pick.");
    entries.set(value.key, value);
  }
  const normalized = freeze({
    source: { name: record.source.name, weekText: record.source.weekText },
    visits: keys.map(key => entries.get(key)),
  });
  return { record: normalized, saved };
}

/** Preserve the complete source text; planned days never imply an outcome or actual date. */
export function createVisitRecord(weekText, sourceName) {
  const original = { name: sourceName, weekText }, saved = source(original);
  return normalize({ source: original, visits: saved.state.picks.map(({ key }) => ({
    key, outcome: "unrecorded", date: null, note: "",
  })) }).record;
}

/** Validate the full input before applying a field-specific, immutable change. */
export function updateVisitRecord(record, occurrenceKey, patch) {
  const current = normalize(record).record;
  fail(patch !== null && typeof patch === "object" && !Array.isArray(patch)
    && [Object.prototype, null].includes(Object.getPrototypeOf(patch)), "Use a visit-field patch.");
  const keys = Reflect.ownKeys(patch);
  fail(keys.every(key => ["outcome", "date", "note"].includes(key)
    && Object.hasOwn(Object.getOwnPropertyDescriptor(patch, key), "value")), "The patch contains an unsupported field.");
  fail(current.visits.some(visit => visit.key === occurrenceKey), "Choose an original pick in this record.");
  return normalize({
    source: current.source,
    visits: current.visits.map(visit => visit.key === occurrenceKey ? { ...visit, ...patch } : visit),
  }).record;
}

/** This public projection retains the original complete pick and exact saved arrangement. */
export function visitRecordRows(record) {
  const { record: current, saved } = normalize(record);
  const dates = Object.fromEntries(calendarWeek(saved.state.weekStart).map(row => [row.day, row.date]));
  return freeze(saved.state.picks.map((original, index) => ({
    key: original.key, originalDay: original.originalDay,
    plannedDay: saved.state.assignments[original.key],
    plannedDate: dates[saved.state.assignments[original.key]] ?? null,
    pick: structuredClone(original.pick),
    outcome: current.visits[index].outcome, date: current.visits[index].date,
    note: current.visits[index].note,
  })));
}

export function makeVisitRecordFile(record, now = new Date()) {
  const { record: current, saved } = normalize(record);
  fail(now instanceof Date && Number.isFinite(now.getTime()), "Use a valid save time.");
  const text = JSON.stringify({
    format: VISIT_RECORD_FORMAT, savedAt: now.toISOString(),
    source: current.source, visits: current.visits,
  }, null, 2) + "\n";
  boundedText(text, VISIT_RECORD_LIMITS.fileBytes, "Visit record file");
  return { filename: `tastetable-visits-${saved.state.weekStart}.json`, text };
}

export function readVisitRecord(text) {
  boundedText(text, VISIT_RECORD_LIMITS.fileBytes, "Visit record file");
  let envelope;
  try { envelope = JSON.parse(text.replace(/^\uFEFF/, "")); }
  catch { throw new TypeError("Choose a valid JSON visit record."); }
  fields(envelope, ["format", "savedAt", "source", "visits"], "Visit record file");
  fail(envelope.format === VISIT_RECORD_FORMAT, "Choose a TasteTable visit record in the supported v1 format.");
  const savedAt = timestamp(envelope.savedAt);
  const record = normalize({ source: envelope.source, visits: envelope.visits }).record;
  return Object.freeze({ record, savedAt });
}

/** A tabular report of admitted visit records; not a replacement backup format. */
import { readVisitRecord, visitRecordRows } from "./visit_record.mjs";
import { readWeekFile } from "./week_file.mjs";

export const VISIT_CSV_COLUMNS = Object.freeze([
  "source_name", "week_start", "source_mode", "source_received_at", "source_saved_at",
  "record_saved_at", "occurrence_key", "venue_name", "entity_id", "kind",
  "original_day", "planned_day", "planned_date", "outcome", "actual_date", "note",
  "original_explanation",
]);

function field(value) {
  if (value === null) return '""';
  if (typeof value !== "string" || !value.isWellFormed()) {
    throw new TypeError("CSV fields must contain valid Unicode text.");
  }
  return '"' + value.replaceAll('"', '""') + '"';
}
const line = values => values.map(field).join(",") + "\r\n";

/** Emit one row per original occurrence, including omitted and unrecorded picks. */
export function renderVisitRecordCsv(text) {
  const { record, savedAt } = readVisitRecord(text);
  const saved = readWeekFile(record.source.weekText);
  const rows = visitRecordRows(record);
  let csv = line(VISIT_CSV_COLUMNS);
  for (const row of rows) {
    csv += line([
      record.source.name, saved.state.weekStart, saved.state.sourceMode,
      saved.receivedAt, saved.savedAt, savedAt, row.key, row.pick.name,
      row.pick.entity_id, row.pick.kind, row.originalDay, row.plannedDay,
      row.plannedDate, row.outcome, row.date, row.note, row.pick.why,
    ]);
  }
  return Object.freeze({
    csv, rowCount: rows.length, weekStart: saved.state.weekStart,
    sourceMode: saved.state.sourceMode, savedAt,
  });
}

/** Ephemeral history for immutable, validated visit_record.mjs snapshots. */
export const VISIT_EDIT_HISTORY_LIMIT = 20;

function sameRecord(a, b) {
  return a === b || !!(a && b &&
    a.source.name === b.source.name && a.source.weekText === b.source.weekText &&
    a.visits.length === b.visits.length && a.visits.every((visit, index) => {
      const other = b.visits[index];
      return visit.key === other.key && visit.outcome === other.outcome &&
        visit.date === other.date && visit.note === other.note;
    }));
}

/** Validation stays with the native model; this helper never reads form fields. */
export function createVisitEditHistory(initial = null) {
  let current = initial, past = [], future = [], active = null;
  const changed = () => active !== null && !sameRecord(active.before, current);
  function close() {
    if (changed()) {
      past.push({before: active.before, after: current, target: active.target});
      if (past.length > VISIT_EDIT_HISTORY_LIMIT) past.shift();
      future = [];
    }
    active = null;
  }
  function reset(record) {
    current = record; past = []; future = []; active = null;
  }
  function record(next, target, grouped = true) {
    if (!current || !next) throw new TypeError("Use a visit record before editing.");
    if (!grouped || active?.target !== target) close();
    if (!active) active = {before: current, target};
    current = next;
    if (!grouped) close();
    return current;
  }
  function undo() {
    close();
    const change = past.pop();
    if (!change) return null;
    future.push(change); current = change.before;
    return {record: current, target: change.target};
  }
  function redo() {
    close();
    const change = future.pop();
    if (!change) return null;
    past.push(change); current = change.after;
    return {record: current, target: change.target};
  }
  return Object.freeze({
    get current() { return current; },
    get canUndo() { return changed() || past.length > 0; },
    get canRedo() { return !changed() && future.length > 0; },
    record, close, reset, undo, redo,
  });
}

/** Portable, user-opened snapshots of an existing TasteTable week. */
import { createWeekPlan, setPickDay } from "./week_plan.mjs";

export const WEEK_FILE_FORMAT = "tastetable.saved-week.v1";

const object = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const copy = (value) => structuredClone(value);
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

function requireValue(condition, message) {
  if (!condition) throw new TypeError(message);
}

function timestamp(value) {
  requireValue(typeof value === "string", "The saved week is missing a valid timestamp.");
  const date = new Date(value);
  requireValue(Number.isFinite(date.getTime()) && date.toISOString() === value,
    "The saved week is missing a valid timestamp.");
  return value;
}

function readInputs(value) {
  requireValue(object(value), "The saved week is missing its original inputs.");
  for (const key of ["cuisines", "music", "films", "constraints"]) {
    requireValue(Array.isArray(value[key]) && value[key].every((item) => typeof item === "string"),
      "The saved week has invalid " + key + " inputs.");
  }
  requireValue(typeof value.city === "string", "The saved week has an invalid city input.");
  return copy(value);
}

function textFields(value, fields, label) {
  requireValue(object(value) && fields.every((field) => typeof value[field] === "string"),
    "The saved response has invalid " + label + ".");
}

function readResponse(value) {
  requireValue(object(value) && object(value.plan), "The saved week is missing its original response.");
  const plan = value.plan;
  requireValue(Array.isArray(plan.meals) && Array.isArray(plan.notes)
    && plan.notes.every((note) => typeof note === "string") && Array.isArray(plan.rejected),
  "The saved response has an incomplete original plan.");
  for (const pick of [...plan.meals, ...(plan.outing == null ? [] : [plan.outing])]) {
    textFields(pick, ["name", "why", "entity_id", "kind", "day"], "original pick fields");
    requireValue(pick.affinity == null || (typeof pick.affinity === "number" && Number.isFinite(pick.affinity)),
      "The saved response has an invalid affinity value.");
    requireValue(pick.fallback === undefined || typeof pick.fallback === "boolean",
      "The saved response has an invalid fallback value.");
  }
  requireValue(object(value.llm_only) && Array.isArray(value.llm_only.meals),
    "The saved response is missing its original comparison plan.");
  for (const pick of [...value.llm_only.meals, value.llm_only.outing]) {
    textFields(pick, ["name", "why", "day"], "comparison pick fields");
  }
  // These fields are native numeric counts, including two inherited raw HTML
  // interpolation sites. A local file must not supply HTML in their place.
  const counts = ["picks", "with_qloo_entity_id", "with_affinity_evidence", "constraint_checked", "unsafe_candidates_rejected"];
  for (const side of ["grounded", "llm_only"]) {
    const values = value.comparison?.[side];
    requireValue(object(values) && counts.every((key) => Number.isSafeInteger(values[key]) && values[key] >= 0),
      "The saved response has invalid comparison counts.");
  }
  for (const rejected of plan.rejected) {
    textFields(rejected, ["name"], "rejected candidate fields");
    requireValue(Array.isArray(rejected.failed), "The saved response has invalid rejected checks.");
    for (const check of rejected.failed) textFields(check, ["constraint", "status", "reason"], "rejected check fields");
  }
  requireValue(Array.isArray(value.trace), "The saved response is missing its original tool trace.");
  for (const entry of value.trace) {
    textFields(entry, ["tool", "result_summary"], "tool trace fields");
    // Native decoder recovery deliberately retains null, arrays and scalar
    // arguments in diagnostics. JSON.stringify + escaping renders them as data.
    requireValue(Object.hasOwn(entry, "args"), "The saved response is missing tool arguments.");
  }
  return copy(value);
}

function restore(value) {
  requireValue(object(value) && value.format === WEEK_FILE_FORMAT,
    "Choose a TasteTable saved-week file in the supported v1 format.");
  const receivedAt = timestamp(value.receivedAt);
  const savedAt = timestamp(value.savedAt);
  requireValue(value.calendarId === null || (typeof value.calendarId === "string" && /^[0-9a-f]{32}$/.test(value.calendarId)),
    "The saved week has an invalid calendar identity.");
  const inputs = readInputs(value.inputs);
  requireValue(object(value.week) && object(value.week.assignments),
    "The saved week is missing its arrangement.");
  const response = readResponse(value.response);
  let state = createWeekPlan(response, value.week.start);
  requireValue(state.weekStart === value.week.start,
    "The saved week must identify the Monday of its displayed week.");
  requireValue(same(inputs.constraints, state.constraints),
    "The saved inputs and the original response have different constraints.");
  const keys = state.picks.map(({ key }) => key);
  requireValue(Object.keys(value.week.assignments).length === keys.length
    && keys.every((key) => Object.hasOwn(value.week.assignments, key)),
  "The saved arrangement must include every original pick exactly once.");
  for (const key of keys) state = setPickDay(state, key, value.week.assignments[key]);
  return { response, inputs, state, receivedAt, savedAt, calendarId: value.calendarId };
}

/** The response is retained whole, including source explanations and tool trace. */
export function makeWeekFile({ response, inputs, state, receivedAt, calendarId }, now = new Date()) {
  const envelope = {
    format: WEEK_FILE_FORMAT,
    receivedAt,
    savedAt: now.toISOString(),
    calendarId,
    inputs: copy(inputs),
    response: copy(response),
    week: { start: state?.weekStart, assignments: copy(state?.assignments) },
  };
  const restored = restore(envelope);
  requireValue(same(state, restored.state),
    "The arranged week no longer matches its original response.");
  return {
    filename: `tastetable-week-${state.weekStart}.json`,
    text: JSON.stringify(envelope, null, 2) + "\n",
  };
}

/** Recreate native immutable state; serialized derived picks are never trusted. */
export function readWeekFile(text) {
  requireValue(typeof text === "string", "The saved week must be a JSON text file.");
  let value;
  try {
    // A UTF-8 BOM is accepted for ordinary editor/file interoperability.
    value = JSON.parse(text.replace(/^\uFEFF/, ""));
  } catch {
    throw new TypeError("This file is not valid JSON. Choose a saved TasteTable week.");
  }
  return restore(value);
}

/** Local scheduling of an existing checked plan. No recommendation or provider calls. */
export const DAYS = Object.freeze([
  "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
]);

function freeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.values(value).forEach(freeze);
    Object.freeze(value);
  }
  return value;
}

function dateKey(date) {
  const year = date.getUTCFullYear();
  if (year < 1 || year > 9999) throw new RangeError("Choose a week within years 0001–9999.");
  return date.toISOString().slice(0, 10);
}

function parseDate(value) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    throw new RangeError("Choose a valid calendar date for your week.");
  }
  const date = new Date(`${value}T12:00:00.000Z`);
  if (!Number.isFinite(date.getTime()) || dateKey(date) !== value) {
    throw new RangeError("Choose a valid calendar date for your week.");
  }
  return date;
}

/** Calendar dates use UTC arithmetic so a daylight-saving change cannot skip a day. */
export function calendarWeek(anchor) {
  const date = parseDate(anchor);
  date.setUTCDate(date.getUTCDate() - (date.getUTCDay() + 6) % 7);
  return DAYS.map((day) => {
    const row = Object.freeze({ day, date: dateKey(date) });
    date.setUTCDate(date.getUTCDate() + 1);
    return row;
  });
}

/** Use the browser's current calendar date, not the UTC date near local midnight. */
export function localDate(now = new Date()) {
  if (!(now instanceof Date) || !Number.isFinite(now.getTime())) {
    throw new RangeError("A valid current date is required.");
  }
  return `${String(now.getFullYear()).padStart(4, "0")}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
}

export function createWeekPlan(response, anchor = localDate()) {
  if (!response?.plan || !Array.isArray(response.plan.meals)) {
    throw new TypeError("The response does not contain a weekly plan.");
  }
  const sourcePlan = structuredClone(response.plan);
  const picks = [...sourcePlan.meals, ...(sourcePlan.outing ? [sourcePlan.outing] : [])]
    .map((pick, index) => {
      if (!pick || !DAYS.includes(pick.day) || !["restaurant", "outing"].includes(pick.kind)
          || typeof pick.entity_id !== "string" || !pick.entity_id.trim()) {
        throw new TypeError("A suggested pick is missing its source identity, kind or day.");
      }
      return { key: `pick-${index}`, originalDay: pick.day, pick };
    });
  return freeze({
    weekStart: calendarWeek(anchor)[0].date,
    sourceMode: response.mock === true ? "mock" : response.mock === false ? "live" : "unknown",
    constraints: structuredClone(response.comparison?.constraints ?? []),
    sourcePlan,
    picks,
    assignments: Object.fromEntries(picks.map(({ key, originalDay }) => [key, originalDay])),
  });
}

export function setWeek(state, anchor) {
  return freeze({ ...state, weekStart: calendarWeek(anchor)[0].date });
}

/** Multiple checked picks may share a day; no pick is duplicated or displaced. */
export function setPickDay(state, key, day) {
  if (!state.picks.some((pick) => pick.key === key)) throw new RangeError("Unknown suggested pick.");
  if (day !== null && !DAYS.includes(day)) throw new RangeError("Choose a weekday or leave this pick off the week.");
  return freeze({ ...state, assignments: { ...state.assignments, [key]: day } });
}

export function resetDays(state) {
  return freeze({
    ...state,
    assignments: Object.fromEntries(state.picks.map(({ key, originalDay }) => [key, originalDay])),
  });
}

export function weekRows(state) {
  return calendarWeek(state.weekStart).map((row) => ({
    ...row, picks: state.picks.filter(({ key }) => state.assignments[key] === row.day),
  }));
}

export function offWeekPicks(state) {
  return state.picks.filter(({ key }) => state.assignments[key] === null);
}

